coration:none;font-size:11px;font-weight:750;cursor:pointer}.tt-search{position:absolute;z-index:2;bottom:0;left:clamp(16px,5vw,64px);right:clamp(16px,5vw,64px);transform:translateY(50%);display:grid;grid-template-columns:1.3fr 1fr .8fr auto;background:white;color:#26383e;box-shadow:0 12px 36px #15242b25;padding:14px;gap:10px}.tt-search label{display:flex;flex-direction:column;gap:6px;font-size:9px;font-weight:800;text-transform:uppercase;padding:4px 10px;border-right:1px solid #e6e8e6}.tt-search input,.tt-search select{border:0;outline:0;font:12px Inter;color:#66747a;min-width:0;background:white}.tt-search button{border:0;background:var(--accent);color:white;padding:0 18px;font-size:11px;font-weight:800;cursor:pointer}.tt-section{padding:78px clamp(20px,5vw,66px)}.tt-head{max-width:680px;margin-bottom:26px}.tt-head h2,.tt-feature h2,.tt-bottom h2{font:500 clamp(27px,3vw,40px)/1.1 Georgia,serif;margin:12px 0}.tt-head p,.tt-feature p{color:#6e7a7a;font-size:12px;line-height:1.8}.tt-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:18px}.tt-card{background:#fff;min-width:0}.tt-card img{width:100%;height:190px;object-fit:cover;display:block}.tt-card>div{padding:18px}.tt-card small{font-size:9px;color:var(--accent);letter-spacing:.12em;text-transform:uppercase;font-weight:800}.tt-card h3{font:22px Georgia,serif;margin:8px 0}.tt-card p{font-size:11px;line-height:1.65;color:#758087}.tt-card a,.tt-feature a{font-size:10px;font-weight:800;color:var(--ink);text-decoration:none}.tt-feature{display:grid;grid-template-columns:1.1fr 1fr;background:#e9e7dc;align-items:center}.tt-feature img{width:100%;height:340px;object-fit:cover}.tt-feature>div{padding:clamp(22px,5vw,65px)}.tt-gallery{display:grid;grid-template-columns:repeat(6,1fr);gap:8px}.tt-gallery img{width:100%;height:125px;object-fit:cover}.tt-bottom{text-align:center;padding:54px 20px;background:var(--ink);color:white}.tt-bottom h2{max-width:560px;margin:0 auto 22px}.tt-footer{display:flex;justify-cont