function renderStats(){$("hfCatalogStats").innerHTML='<div class="hf-catalog-stat"><strong>'+categories.filter(c=>c.is_active).length+'</strong><span>Active categories</span></div><div class="hf-catalog-stat"><strong>'+products.filter(p=>p.is_active).length+'</strong><span>Active products</span></div><div class="hf-catalog-stat"><strong>'+products.reduce((n,p)=>n+Number(p.stock||0),0).toLocaleString("en-BD")+'</strong><span>Total units in stock</span></div>';}
function renderCategories(){$("hfCategoryList").innerHTML=categories.length?categories.map(c=>'<div class="hf-category-row"><div><strong>'+esc(c.name)+'</strong><small>/'+esc(c.slug)+' · '+(c.is_active?"Active":"Archived")+'</small></div><div class="hf-catalog-row-actions"><button class="hf-catalog-mini" data-category-edit="'+esc(c.id)+'">Edit</button><button class="hf-catalog-mini archive" data-category-active="'+esc(c.id)+'" data-active="'+String(c.is_active)+'">'+(c.is_active?"Archive":"Restore")+'</button></div></div>').join(""):'<div class="hf-catalog-empty">No categories yet. Add your first category above.</div>';
document.querySelectorAll("[data-category-edit]").forEach(b=>b.addEventListener("click",()=>editCategory(b.dataset.categoryEdit)));
document.querySelectorAll("[data-category-active]").forEach(b=>b.addEventListener("click",()=>toggleCategory(b.dataset.categoryActive,b.dataset.active==="true")));
