  background:linear-gradient(135deg,#c98242 0%,#a95f2e 100%);
  border-color:#a95f2e;
  color:#fff!important;
  box-shadow:0 7px 18px rgba(169,95,46,.18);
}
.hf-wpt-browser-button:hover{
  background:linear-gradient(135deg,#b96f35 0%,#914b25 100%);
  border-color:#914b25;
  transform:translateY(-1px);
}

/* Clothing & Fashion template previews — four distinct commerce identities */
.hf-wpt-templates-page:has(.hf-fashion){--wpt-fashion-ink:#252321}
.hf-fashion{font-family:"DM Sans",sans-serif;background:#f7f4ef;color:#252321;min-height:100%}
.hf-fashion-utility{display:flex;justify-content:space-between;gap:12px;padding:9px 3%;background:#252321;color:#fff;font-size:9px;font-weight:800;letter-spacing:.14em}
.hf-fashion-utility span{font-weight:500;letter-spacing:.04em;opacity:.8}
.hf-fashion-header{display:grid;grid-template-columns:1fr minmax(150px,1.1fr) auto;align-items:center;gap:22px;padding:18px 4%;background:#fffdfa}
.hf-fashion-wordmark{font-family:"Cormorant Garamond",serif;font-size:25px;font-weight:700;letter-spacing:.08em}
.hf-fashion-search{display:flex;gap:9px;align-items:center;border-bottom:1px solid #cfc7be;padding:9px;color:#777}
.hf-fashion-search input{width:100%;border:0;outline:0;background:transparent;font:inherit;font-size:11px}
.hf-fashion-actions{display:flex;align-items:center;gap:16px;font-size:10px}
.hf-fashion-bag{border:1px solid #252321;background:transparent;padding:9px 14px;font:inherit}
.hf-fashion-bag b{margin-left:8px}
.hf-fashion-nav{display:flex;justify-content:center;gap:24px;padding:12px 3%;background:#fffdfa;border-top:1px solid #eee7df}
.hf-fashion-nav button{border:0;background:none;color:inherit;font-size:10px;font-weight:700}
.hf-fashion-hero{position:relative;min-height:340px;display:grid;grid-template-columns:1fr 1fr;background:#eee7df;overflow:hidden}
.hf-fashion-hero>img{position:absolute;inset:0;width:100%;height:100%;object-fit:cover}
.hf-fashion-hero-copy{position:relative;z-index:1;align-self:center;width:min(48%,470px);margin:34px 0 34px 6%;padding:25px;background:rgba(255,253,250,.93);backdrop-filter:blur(12px)}
.hf-fashion-hero-copy small,.hf-fashion-story small,.hf-fashion-newsletter small{font-size:9px;font-weight:800;letter-spacing:.16em}
.hf-fashion-hero-copy h2{font-family:"Cormorant Garamond",serif;font-size:clamp(34px,5vw,62px);line-height:.98;font-weight:600;margin:14px 0}
.hf-fashion-hero-copy p{font-size:12px;line-height:1.7;color:#6d655d}
.hf-fashion-hero-copy button{background:#252321;color:#fff;border:0;padding:12px 18px;font-size:10px;font-weight:800}
.hf-fashion-hero-index{position:absolute;right:20px;bottom:18px;color:#fff;font-size:10px;letter-spacing:.1em}
.hf-fashion-trust{display:flex;justify-content:space-around;gap:12px;padding:14px 3%;background:#fffdfa;border-bottom:1px solid #e7e0d7;font-size:10px}
.hf-fashion-section{padding:34px 4%}
.hf-fashion-section-head{display:flex;align-items:end;justify-content:space-between;margin-bottom:18px}
.hf-fashion-section-head small{font-size:9px;letter-spacing:.15em;font-weight:800;color:#8a7665}
.hf-fashion-section-head h3{font-family:"Cormorant Garamond",serif;font-size:30px;font-weight:600;margin:4px 0}
.hf-fashion-collections{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:10px}
.hf-fashion-collection{min-height:110px;text-align:left;border:0;padding:14px;background:#e9e0d6;color:#252321;display:flex;flex-direction:column;justify-content:space-between}
.hf-fashion-collection--1{background:#e4d8cb}.hf-fashion-collection--2{background:#ddd5cb}.hf-fashion-collection--3{background:#d4d7d2}
.hf-fashion-collection span{font-size:9px;opacity:.65}.hf-fashion-collection strong{font-family:"Cormorant Garamond",serif;font-size:21px}.hf-fashion-collection small{font-size:9px}
.hf-fashion-products{background:#fffdfa}
.hf-fashion-product-grid{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:12px}
.hf-fashion-product-grid .hf-shop-product{background:transparent;border:0}
.hf-fashion-product-grid .hf-shop-product-image{aspect-ratio:3/4;position:relative;background:#ece8e2;overflow:hidden}
.hf-fashion-product-grid .hf-shop-product-image img{width:100%;height:100%;object-fit:cover}
.hf-fashion-product-grid .hf-shop-product-tag{position:absolute;left:8px;top:8px;background:#fffdfa;padding:5px 7px;font-size:8px;letter-spacing:.08em}
.hf-fashion-product-grid .hf-shop-add{position:absolute;right:8px;bottom:8px;width:29px;height:29px;border:0;border-radius:50%;background:#252321;color:#fff;font-size:18px}
.hf-fashion-product-grid .hf-shop-product-info{padding:10px 1px;display:grid;gap:4px}
.hf-fashion-product-grid .hf-shop-product-info small{font-size:9px;color:#80776e}
.hf-fashion-product-grid .hf-shop-product-info strong{font-size:11px}
.hf-fashion-product-grid .hf-shop-product-info>div{display:flex;justify-content:space-between;font-size:10px}
.hf-fashion-story{display:grid;grid-template-columns:1fr .9fr;gap:24px;align-items:center;padding:36px 6%;background:#eee7df}
.hf-fashion-story h3{font-family:"Cormorant Garamond",serif;font-size:34px;line-height:1.05;font-weight:600}
.hf-fashion-story p{font-size:11px;line-height:1.8;color:#655d55}
.hf-fashion-story a{font-size:10px;font-weight:800;text-decoration:underline;text-underline-offset:4px}
.hf-fashion-story img{width:100%;height:230px;object-fit:cover}
.hf-fashion-newsletter{padding:34px 5%;text-align:center;background:#252321;color:#fff}
.hf-fashion-newsletter h3{font-family:"Cormorant Garamond",serif;font-size:30px;font-weight:600;margin:8px}
.hf-fashion-newsletter p,.hf-fashion-newsletter span{font-size:10px;color:#d2cbc2}
.hf-fashion--boutique-ethnic-wear{background:#f8f2eb}
.hf-fashion--boutique-ethnic-wear .hf-fashion-utility{background:#4b352c}
.hf-fashion--boutique-ethnic-wear .hf-fashion-wordmark{font-family:"Playfair Display",serif;color:#8b4e3c}
.hf-fashion--streetwear-sneaker-store{background:#f1f0ed;color:#17191d}
.hf-fashion--streetwear-sneaker-store .hf-fashion-utility{background:#17191d;color:#d6ff3f}
.hf-fashion--streetwear-sneaker-store .hf-fashion-wordmark{font-family:"Manrope",sans-serif;font-weight:900;letter-spacing:-.06em}
.hf-fashion--streetwear-sneaker-store .hf-fashion-hero-copy{background:rgba(23,25,29,.94);color:#fff}
.hf-fashion--streetwear-sneaker-store .hf-fashion-hero-copy p{color:#c4c6c9}
.hf-fashion--streetwear-sneaker-store .hf-fashion-hero-copy button{background:#d6ff3f;color:#17191d}
.hf-fashion--streetwear-sneaker-store .hf-fashion-collection{background:#d6ff3f}
.hf-fashion--fashion-retailer{background:#f6f7f8}
.hf-fashion--fashion-retailer .hf-fashion-utility{background:#426b77}
.hf-fashion--fashion-retailer .hf-fashion-wordmark{font-family:"Manrope",sans-serif;font-weight:900}
.hf-fashion--fashion-retailer .hf-fashion-collection{background:#e5ecee}
@media(max-width:700px){.hf-fashion-header{grid-template-columns:1fr auto;gap:10px;padding:13px 4%}.hf-fashion-search{grid-column:1/-1;grid-row:2}.hf-fashion-nav{justify-content:flex-start;overflow:auto;white-space:nowrap;gap:17px}.hf-fashion-hero{min-height:390px;display:block}.hf-fashion-hero-copy{width:80%;margin:42px 0 35px 5%;padding:18px}.hf-fashion-hero-index{right:12px}.hf-fashion-trust{display:grid;grid-template-columns:1fr 1fr}.hf-fashion-collections{grid-template-columns:repeat(2,minmax(0,1fr))}.hf-fashion-product-grid{grid-template-columns:repeat(2,minmax(0,1fr));gap:10px}.hf-fashion-story{grid-template-columns:1fr}.hf-fashion-story img{height:180px}}


/* Fashion preview polish: image-led discovery, restrained motion and depth */
.hf-fashion{overflow:hidden;--fashion-ease:cubic-bezier(.2,.7,.2,1)}
.hf-fashion-hero{min-height:440px;isolation:isolate}
.hf-fashion-hero>img{transition:transform 1.2s var(--fashion-ease);will-change:transform}
.hf-fashion-hero:hover>img{transform:scale(1.035)}
.hf-fashion-hero-overlay{position:absolute;inset:0;background:linear-gradient(90deg,rgba(18,17,16,.34),rgba(18,17,16,.02) 68%);pointer-events:none}
.hf-fashion-hero-copy{box-shadow:0 24px 70px rgba(30,24,20,.12);animation:hfFashionRise .8s var(--fashion-ease) both}
.hf-fashion-hero-copy button,.hf-fashion-bag,.hf-fashion-nav button,.hf-fashion-collection,.hf-fashion-product-grid .hf-shop-add{transition:transform .28s var(--fashion-ease),background-color .28s ease,color .28s ease,box-shadow .28s ease}
.hf-fashion-hero-copy button:hover{transform:translateY(-3px);box-shadow:0 12px 26px rgba(0,0,0,.18)}
.hf-fashion-nav button{position:relative;padding:6px 0}
.hf-fashion-nav button:after{content:"";position:absolute;left:0;right:100%;bottom:0;height:1px;background:currentColor;transition:right .25s ease}
.hf-fashion-nav button:hover:after{right:0}
.hf-fashion-hero-caption{position:absolute;left:4%;bottom:18px;z-index:2;color:#fff;font-size:9px;font-weight:800;letter-spacing:.2em;text-shadow:0 2px 12px rgba(0,0,0,.45)}
.hf-fashion-collections{grid-template-columns:repeat(4,minmax(0,1fr));gap:14px}
.hf-fashion-collection{position:relative;isolation:isolate;overflow:hidden;min-height:220px;padding:16px;color:#fff;background:#34302d;box-shadow:0 8px 24px rgba(30,24,20,.08);transform-style:preserve-3d}
.hf-fashion-collection img{position:absolute;inset:0;width:100%;height:100%;object-fit:cover;z-index:-2;transition:transform .8s var(--fashion-ease),filter .5s ease}
.hf-fashion-collection-shade{position:absolute;inset:0;z-index:-1;background:linear-gradient(180deg,rgba(0,0,0,.08),rgba(0,0,0,.58))}
.hf-fashion-collection-index{font-size:10px;letter-spacing:.12em}
.hf-fashion-collection strong{font-family:var(--sf-display,"Cormorant Garamond",serif);font-size:clamp(19px,2vw,28px);text-shadow:0 2px 12px rgba(0,0,0,.35)}
.hf-fashion-collection small{font-size:9px}
.hf-fashion-collection:hover{transform:translateY(-5px) rotateX(1.5deg);box-shadow:0 18px 38px rgba(30,24,20,.18)}
.hf-fashion-collection:hover img{transform:scale(1.09);filter:saturate(1.12)}
.hf-fashion-product-grid .hf-shop-product{transition:transform .35s var(--fashion-ease),box-shadow .35s ease}
.hf-fashion-product-grid .hf-shop-product:hover{transform:translateY(-6px);box-shadow:0 18px 34px rgba(34,29,25,.09)}
.hf-fashion-product-grid .hf-shop-product-image img{transition:transform .7s var(--fashion-ease),filter .4s ease}
.hf-fashion-product-grid .hf-shop-product:hover .hf-shop-product-image img{transform:scale(1.065);filter:saturate(1.05)}
.hf-fashion-product-grid .hf-shop-add:hover{transform:scale(1.12) rotate(90deg)}
.hf-fashion-products-foot{display:flex;justify-content:space-between;gap:16px;align-items:center;padding:20px 0 2px;border-top:1px solid #e7e0d7;font-size:10px;color:#71685f}
.hf-fashion-products-foot a,.hf-fashion-journal-head a{font-weight:800;text-decoration:underline;text-underline-offset:4px}
.hf-fashion-story{overflow:hidden}
.hf-fashion-story img{transition:transform .9s var(--fashion-ease);box-shadow:0 18px 44px rgba(30,24,20,.12)}
.hf-fashion-story:hover img{transform:scale(1.035) rotate(.4deg)}
.hf-fashion-journal{padding:38px 4%;background:#f7f4ef}
.hf-fashion-journal-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:18px}
.hf-fashion-journal-card{background:#fffdfa;min-width:0;transition:transform .35s var(--fashion-ease),box-shadow .35s ease}
.hf-fashion-journal-card:hover{transform:translateY(-5px);box-shadow:0 16px 36px rgba(30,24,20,.1)}
.hf-fashion-journal-image{height:220px;position:relative;overflow:hidden;background:#e8e0d7}
.hf-fashion-journal-image img{width:100%;height:100%;object-fit:cover;transition:transform .8s var(--fashion-ease)}
.hf-fashion-journal-card:hover .hf-fashion-journal-image img{transform:scale(1.06)}
.hf-fashion-journal-image span{position:absolute;left:12px;top:12px;background:rgba(255,253,250,.9);padding:6px 8px;font-size:9px}
.hf-fashion-journal-copy{padding:16px}
.hf-fashion-journal-copy small{font-size:9px;letter-spacing:.13em;font-weight:800;color:#907a68}
.hf-fashion-journal-copy h4{font-family:"Cormorant Garamond",serif;font-size:24px;line-height:1.05;margin:9px 0}
.hf-fashion-journal-copy p{font-size:11px;line-height:1.65;color:#6d655d}
.hf-fashion-journal-copy a{font-size:10px;font-weight:800;text-decoration:underline;text-underline-offset:4px}
.hf-fashion--streetwear-sneaker-store .hf-fashion-collection{border:1px solid rgba(23,25,29,.16)}
.hf-fashion--streetwear-sneaker-store .hf-fashion-collection-shade{background:linear-gradient(180deg,rgba(10,12,15,.05),rgba(10,12,15,.75))}
.hf-fashion--streetwear-sneaker-store .hf-fashion-collection strong{font-family:"Space Grotesk",sans-serif;text-transform:uppercase}
.hf-fashion--boutique-ethnic-wear .hf-fashion-collection-shade{background:linear-gradient(180deg,rgba(47,30,24,.08),rgba(47,30,24,.65))}
.hf-fashion--fashion-retailer .hf-fashion-collection-shade{background:linear-gradient(180deg,rgba(28,48,55,.06),rgba(28,48,55,.68))}
@keyframes hfFashionRise{from{opacity:0;transform:translateY(18px)}to{opacity:1;transform:translateY(0)}}
@media(prefers-reduced-motion:reduce){.hf-fashion *, .hf-fashion *:before,.hf-fashion *:after{animation-duration:.01ms!important;animation-iteration-count:1!important;scroll-behavior:auto!important;transition-duration:.01ms!important}}
@media(max-width:700px){.hf-fashion-hero{min-height:420px}.hf-fashion-collections{grid-template-columns:repeat(2,minmax(0,1fr));gap:9px}.hf-fashion-collection{min-height:175px;padding:12px}.hf-fashion-journal-grid{grid-template-columns:1fr;gap:12px}.hf-fashion-journal-image{height:230px}.hf-fashion-products-foot{align-items:flex-start;flex-direction:column}}

.hf-fashion-nav button.is-active{font-weight:900;text-decoration:underline;text-underline-offset:5px}.hf-fashion-collection:focus-visible,.hf-fashion-nav button:focus-visible,.hf-fashion-product-grid .hf-shop-add:focus-visible{outline:2px solid currentColor;outline-offset:3px}


/* Medicine & Pharmacy template family */
.hf-pharmacy{--pharmacy-accent:#168b83;--pharmacy-ink:#173b43;--pharmacy-paper:#f3faf8;background:var(--pharmacy-paper);color:var(--pharmacy-ink);font-family:Inter,Arial,sans-serif;overflow:hidden}
.hf-pharmacy--carewell-health-store{--pharmacy-accent:#6a9c69;--pharmacy-ink:#27443a;--pharmacy-paper:#f7faf4}
.hf-pharmacy--clinic-medical-supplies{--pharmacy-accent:#3975a8;--pharmacy-ink:#1d3550;--pharmacy-paper:#f4f8fc}
.hf-pharmacy--express-medicine-delivery{--pharmacy-accent:#e07b42;--pharmacy-ink:#263746;--pharmacy-paper:#f8f8f6}
.hf-pharmacy-alert{padding:10px 5%;background:var(--pharmacy-ink);color:#fff;font-size:9px;letter-spacing:.12em;font-weight:800}
.hf-pharmacy-alert span{color:#a8e2d7;font-size:14px}.hf-pharmacy-alert b{margin:0 8px;color:#b5d8d1}
.hf-pharmacy-header{display:flex;align-items:center;justify-content:space-between;gap:20px;padding:22px 5%;background:#fff}
.hf-pharmacy-brand{font-size:21px;font-weight:900;letter-spacing:-.06em;color:var(--pharmacy-ink);text-decoration:none}.hf-pharmacy-brand small{display:block;font-size:7px;letter-spacing:.2em;color:var(--pharmacy-accent)}
.hf-pharmacy-search{display:flex;align-items:center;gap:10px;max-width:430px;flex:1;padding:12px 15px;border:1px solid #dce7e4;border-radius:999px;color:var(--pharmacy-accent)}
.hf-pharmacy-search input{width:100%;border:0;outline:0;background:transparent;font:inherit;font-size:11px}
.hf-pharmacy-actions{display:flex;align-items:center;gap:15px;font-size:10px}.hf-pharmacy-actions button{border:0;border-radius:999px;padding:12px 17px;background:var(--pharmacy-ink);color:#fff;font-weight:800}
.hf-pharmacy-nav{display:flex;gap:8px;overflow:auto;padding:12px 5%;background:#fff;border-top:1px solid #edf1ef}
.hf-pharmacy-nav button{white-space:nowrap;border:1px solid #e1e9e6;border-radius:999px;background:#fff;padding:9px 14px;color:var(--pharmacy-ink);font-size:9px}.hf-pharmacy-nav button.is-active{background:var(--pharmacy-ink);color:#fff}
.hf-pharmacy-hero{display:grid;grid-template-columns:1.02fr .98fr;min-height:380px;margin:22px 4%;border-radius:20px;overflow:hidden;background:#e3f0ed}
.hf-pharmacy-hero-copy{align-self:center;padding:clamp(22px,4vw,56px)}.hf-pharmacy-hero-copy>small,.hf-pharmacy-section-head small,.hf-pharmacy-editorial small{font-size:8px;font-weight:900;letter-spacing:.17em;color:var(--pharmacy-accent)}
.hf-pharmacy-hero-copy h2{font-size:clamp(28px,4.3vw,55px);line-height:1.03;letter-spacing:-.05em;margin:14px 0;color:var(--pharmacy-ink)}
.hf-pharmacy-hero-copy p{max-width:430px;color:#526c6b;font-size:12px;line-height:1.8}
.hf-pharmacy-hero-copy button{margin-top:14px;padding:13px 20px;border:0;border-radius:999px;background:var(--pharmacy-accent);color:#fff;font-weight:850;font-size:10px;cursor:pointer;transition:transform .25s,box-shadow .25s}
.hf-pharmacy-hero-copy button:hover{transform:translateY(-3px);box-shadow:0 12px 24px #173b4328}
.hf-pharmacy-trust{display:flex;flex-wrap:wrap;gap:12px;margin-top:20px;font-size:8px;color:#49615e}
.hf-pharmacy-hero-media{position:relative;min-height:300px;overflow:hidden}.hf-pharmacy-hero-media img{width:100%;height:100%;position:absolute;inset:0;object-fit:cover;transition:transform 1s}.hf-pharmacy-hero:hover .hf-pharmacy-hero-media img{transform:scale(1.045)}
.hf-pharmacy-hero-media span{position:absolute;right:18px;bottom:18px;padding:10px 13px;border-radius:999px;background:#fff;color:var(--pharmacy-ink);font-size:8px;font-weight:900;letter-spacing:.12em}
.hf-pharmacy-quicklinks{display:grid;grid-template-columns:repeat(4,1fr);gap:12px;margin:26px 5%}
.hf-pharmacy-tile{position:relative;min-height:155px;overflow:hidden;border:0;border-radius:13px;text-align:left;background:#d9e7e2;color:#fff;cursor:pointer;isolation:isolate}
.hf-pharmacy-tile:before{content:"";position:absolute;inset:0;background:linear-gradient(0deg,#102b30c9,transparent 75%);z-index:1}
.hf-pharmacy-tile img{position:absolute;inset:0;width:100%;height:100%;object-fit:cover;z-index:-1;transition:transform .7s}
.hf-pharmacy-tile:hover img{transform:scale(1.1) rotate(-1deg)}
.hf-pharmacy-tile span,.hf-pharmacy-tile strong,.hf-pharmacy-tile small{position:relative;z-index:2;display:block;margin:0 12px}.hf-pharmacy-tile span{padding-top:15px;font-size:8px}.hf-pharmacy-tile strong{margin-top:42px;font-size:14px}.hf-pharmacy-tile small{font-size:8px;margin-top:3px}
.hf-pharmacy-products{padding:30px 5% 38px;background:#fff}.hf-pharmacy-section-head{display:flex;justify-content:space-between;align-items:end;gap:14px;margin-bottom:18px}
.hf-pharmacy-section-head h3{font-size:clamp(22px,3vw,34px);letter-spacing:-.04em;margin:7px 0;color:var(--pharmacy-ink)}
.hf-pharmacy-section-head p{font-size:9px;color:#778681;margin:0}.hf-pharmacy-section-head>span{font-size:8px;font-weight:900;letter-spacing:.1em;color:var(--pharmacy-accent)}
.hf-pharmacy-product-grid{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:12px}.hf-pharmacy-product-grid .hf-shop-product{border:1px solid #e6eeeb;border-radius:13px;overflow:hidden;background:#fff;transition:transform .25s,box-shadow .25s}.hf-pharmacy-product-grid .hf-shop-product:hover{transform:translateY(-5px);box-shadow:0 15px 35px #193c3518}
.hf-pharmacy-product-grid .hf-shop-product-image{position:relative;aspect-ratio:1.1;background:#f1f6f4}.hf-pharmacy-product-grid .hf-shop-product-image img{width:100%;height:100%;object-fit:cover}
.hf-pharmacy-product-grid .hf-shop-product-info{padding:11px}.hf-pharmacy-product-grid .hf-shop-product-info strong{display:block;font-size:11px}.hf-pharmacy-product-grid .hf-shop-product-info small{font-size:8px;color:var(--pharmacy-accent)}.hf-pharmacy-product-grid .hf-shop-add{background:var(--pharmacy-accent);color:#fff}
.hf-pharmacy-orderbar{display:flex;align-items:center;justify-content:space-between;margin-top:22px;padding:16px 18px;border-radius:13px;background:var(--pharmacy-ink);color:#fff}
.hf-pharmacy-orderbar small,.hf-pharmacy-orderbar strong{display:block}.hf-pharmacy-orderbar small{font-size:8px;letter-spacing:.14em;color:#b8d9d2}.hf-pharmacy-orderbar strong{margin-top:4px;font-size:14px}
.hf-pharmacy-orderbar button{border:0;border-radius:999px;padding:13px 20px;background:#fff;color:var(--pharmacy-ink);font-weight:900;cursor:pointer}
.hf-pharmacy-editorial{display:grid;grid-template-columns:1fr .9fr;gap:28px;align-items:center;margin:34px 5%;padding:24px;border-radius:17px;background:#eaf2ef}
.hf-pharmacy-editorial h3{font-size:clamp(22px,3vw,36px);line-height:1.08;margin:12px 0}.hf-pharmacy-editorial p{font-size:10px;line-height:1.8;color:#61736e}.hf-pharmacy-editorial a{display:inline-block;margin-top:8px;color:var(--pharmacy-accent);font-size:9px;font-weight:900}
