,e=>{state.filters.brand=e.target.value;const el=root.querySelector("#sfProductResults");if(el)el.innerHTML=productGrid(filteredProducts());bindDynamic();});root.querySelector("#sfAvailabilityFilter")?.addEventListener("change",e=>{state.filters.availability=e.target.value;const el=root.querySelector("#sfProductResults");if(el)el.innerHTML=productGrid(filteredProducts());bindDynamic();});root.querySelector("#sfCheckoutForm")?.addEventListener("submit",submitOrder);root.querySelector("#sfArea")?.addEventListener("change",updateCheckoutSummary);root.querySelector("#sfTrackForm")?.addEventListener("submit",trackOrder);root.querySelector("#sfReturnForm")?.addEventListener("submit",submitReturnRequest);root.querySelector("#sfBulkQuickOrder")?.addEventListener("submit",submitBulkQuickOrder);root.querySelector("#sfBulkSearch")?.addEventListener("input",e=>{const q=e.target.value.toLowerCase();root.querySelectorAll("[data-bulk-row]").forEach(row=>row.hidden=!row.dataset.bulkName.includes(q));});root.querySelector("#sfBulkEnquiry")?.addEventListener("submit",submitQuote);bindDynamic();}
function bindDynamic(){root.querySelectorAll('[data-reorder-tracked]').forEach(b=>b.addEventListener('click',reorderTrackedOrder));root.querySelectorAll("[data-add]").forEach(b=>b.addEventListener("click",()=>addToCart(b.dataset.add)));root.querySelectorAll("[data-buy-now]").forEach(b=>b.addEventListener("click",()=>{addToCart(b.dataset.buyNow,Number(root.querySelector("#sfProductQty")?.value)||1,true);}));root.querySelectorAll("[data-wish]").forEach(b=>b.addEventListener("click",()=>toggleWish(b.dataset.wish)));root.querySelectorAll("[data-filter-category]").forEach(b=>b.addEventListener("click",()=>{state.filters.category=b.dataset.filterCategory;const el=root.querySelector("#sfProductResults");if(el)el.innerHTML=productGrid(filteredProducts());root.querySelectorAll("[data-filter-category]").forEach(x=>x.classList.toggle("is-active",x===b));bindDynamic();}));root.querySelectorAll("[data-cart-qty]").forEach(b=>b.addEventListener("click",()=>{const p=getProduct(b.dataset.product);changeCart(b.dataset.product,Number(b.dataset.cartQty)*(p?quantityStep(p):1));}));root.querySelectorAll("[data-cart-input]").forEach(input=>input.addEventListener("change",()=>{const p=getProduct(input.dataset.product),row=state.cart.find(x=>x.product_id===input.dataset.product);if(!p||!row)return;const value=Number(input.value),minimum=quantityMinimum(p);if(!Number.isFinite(value)||value<minimum||value>Number(p.stock)){notify("Enter a quantity between "+minimum+" and "+Number(p.stock)+".");render();return;}row.quantity=value;saveLocal();render();}));root.querySelectorAll("[data-remove]").forEach(b=>b.addEventListener("click",()=>{state.cart=state.cart.filter(x=>x.product_id!==b.dataset.remove);saveLocal();render();}));root.querySelectorAll("[data-qty]").forEach(b=>b.addEventListener("click",()=>{const input=root.querySelector("#sfProductQty");if(input){const step=Number(input.step)||1;input.value=Math.max(Number(input.min)||step,Math.min(Number(input.max)||999,Number(input.value||step)+Num