/* News & Media Studio — four distinct editorial and broadcast templates. */
(function(){
"use strict";
const params=new URLSearchParams(location.search);
if(params.get("category")!=="news-media")return;
const $=id=>document.getElementById(id),esc=v=>String(v??"").replace(/[&<>"']/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[c]));
const root="/assets/news-media/";
let data,active=Math.max(0,Math.min(3,(Number(params.get("template")||1)-1))),page=params.get("page")||"home",query="";
const pageLabel=k=>data.pages.find(p=>p.key===k)?.title||"Latest Stories";
const pageUrl=(key)=>"./storefront.html?news-template="+encodeURIComponent(data.templates[active].key)+"&page="+encodeURIComponent(key);
function image(path,alt,cls){if(path.includes("#"))return '<svg class="'+(cls||"nms-image")+'" role="img" aria-label="'+esc(alt)+'"><use href="/'+esc(path)+'"></use></svg>';return '<img class="'+(cls||"nms-image")+'" src="/'+esc(path)+'" alt="'+esc(alt)+'" loading="lazy">';}
function card(t,story,i){const p=t.pageImages[page]||t.pageImages.latest,asset=p[i%p.length];return '<article class="nms-story-card">'+image(asset,story[0])+'<div class="nms-story-copy"><small>'+esc(story[1])+' · '+String(i+1).padStart(2,"0")+'</small><h3>'+esc(story[0])+'</h3><p>'+esc(story[2])+'</p><a href="#" data-nms-page="article">Read story <span>↗</span></a></div></article>';}
function storiesFor(t){return t.stories.filter(s=>!query||s.join(" ").toLowerCase().includes(query.toLowerCase()));}
function renderHome(t){const imgs=t.pageImages.home;const feature=t.stories[0],secondary=t.stories.slice(1,4);return '<section class="nms-hero"><div class="nms-hero-image">'+image(imgs[0],t.imageAlts[0],"nms-hero-photo")+'<span class="nms-hero-caption">THE EDITORIAL DESK · ILLUSTRATIVE PREVIEW</span></div><div class="nms-hero-copy"><small>'+esc(t.tag)+'</small><h1>'+esc(t.hero)+'</h1><p>'+esc(t.copy)+'</p><a class="nms-primary" href="#" data-nms-page="latest">'+esc(t.cta)+' ↗</a><div class="nms-hero-meta"><span>Independent perspective</span><span>Context before noise</span></div></div></section><section class="nms-lead-grid"><article class="nms-lead-story"><div class="nms-lead-art">'+image(imgs[1],t.imageAlts[1])+'</div><div><small>EDITOR’S PICK · '+esc(feature[1])+'</small><h2>'+esc(feature[0])+'</h2><p>'+esc(feature[2])+'</p><a href="#" data-nms-page="article">Read the feature ↗</a></div></article><aside class="nms-side-stories"><small>MORE TO EXPLORE</small>'+secondary.map((s,i)=>'<a href="#" data-nms-page="article"><span>0'+(i+1)+'</span><div><small>'+esc(s[1])+'</small><strong>'+esc(s[0])+'</strong></div>↗</a>').join("")+'</aside></section><section class="nms-section"><div class="nms-section-head"><div><small>THE LATEST</small><h2>Stories worth your attention.</h2></div><a href="#" data-nms-page="latest">All stories ↗</a></div><div class="nms-card-grid">'+t.stories.slice(4,7).map((s,i)=>card(t,s,i+1)).join("")+'</div></section><section class="nms-briefing"><div><small>THE DAILY BRIEFING</small><h2>Make space for informed reading.</h2><p>Get a considered selection of stories and explainers. Preview only — no subscription is submitted.</p></div><form id="nmsNewsletter"><input type="email" name="email" placeholder="Your email address" required aria-label="Email address"><button type="submit">Preview signup ↗</button></form></section>';}
function renderPage(t){if(page==="home")return renderHome(t);const storyList=storiesFor(t),imgs=t.pageImages[page]||t.pageImages.latest;const article=page==="article",content=article?t.stories[0]:null;let hero='<section class="nms-page-hero"><div><small>'+esc(t.eyebrow)+' / '+esc(pageLabel(page).toUpperCase())+'</small><h1>'+esc(article?content[0]:pageLabel(page))+'</h1><p>'+esc(article?content[2]:"A carefully edited collection of reporting, useful context and perspectives from the "+t.name+" editorial team. All stories and examples in this template are illustrative sample content.")+'</p></div>'+image(imgs[0],pageLabel(page),"nms-page-hero-art")+'</section>';
if(article)return hero+'<article class="nms-article"><div class="nms-article-meta"><span>ILLUSTRATIVE EDITORIAL SAMPLE</span><span>6 MIN READ</span><span>EDITORIAL DESK</span></div><p class="nms-article-intro">'+esc(content[2])+'</p><h2>Start with the context</h2><p>This sample article demonstrates the long-form editorial layout. A real publisher can replace this copy with verified reporting, source notes, named authors, publication dates and relevant links before launch.</p>'+image(imgs[1],pageLabel(page)+" supporting visual")+'<h2>What readers should take away</h2><p>Good journalism separates what is known, what remains uncertain and what deserves further investigation. Each published story should link to primary sources where possible and clearly label analysis, opinion and sponsored material.</p><blockquote>Clear context helps readers make sense of complex stories.</blockquote><p>Editorial content, quotes, dates and claims must be reviewed by the publisher before publication.</p><a class="nms-primary" href="#" data-nms-page="latest">Back to latest stories ↗</a></article>';
const cards=storyList.map((s,i)=>card(t,s,i)).join("");
const extra='<section class="nms-topic-tools"><label>Search this section <input id="nmsSearch" value="'+esc(query)+'" placeholder="Search headlines, topics and ideas"></label><span>'+storyList.length+' illustrative stories</span></section>';
return hero+extra+'<section class="nms-card-grid nms-card-grid--page">'+(cards||'<p class="nms-empty">No sample stories match that search.</p>')+'</section><section class="nms-more-links"><a href="#" data-nms-page="newsletters">Get the briefing ↗</a><a href="#" data-nms-page="standards">Editorial standards ↗</a><a href="#" data-nms-page="contact">Contact the newsroom ↗</a></section>';}
function render(){const t=data.templates[active],host=$("wpStorefront");host.hidden=false;host.dataset.template=t.key;host.innerHTML='<div class="nms-site" style="--nms-accent:'+t.accent+';--nms-ink:'+t.ink+';--nms-paper:'+t.paper+';--nms-surface:'+t.surface+';--nms-font:'+JSON.stringify(t.font)+'"><div class="nms-topline">'+esc(t.eyebrow)+' <span>ILLUSTRATIVE TEMPLATE PREVIEW · NOT LIVE NEWS</span></div><header class="nms-header"><a class="nms-brand" href="#" data-nms-page="home">'+esc(t.brand)+'<small>'+esc(t.short)+'</small></a><nav>'+data.pages.slice(1,8).map(p=>'<a href="#" data-nms-page="'+p.key+'">'+esc(p.title)+'</a>').join("")+'</nav><button type="button" class="nms-menu" aria-label="Toggle navigation">☰</button><a class="nms-header-cta" href="#" data-nms-page="newsletters">Get the briefing ↗</a></header><main>'+renderPage(t)+'</main><footer class="nms-footer"><div><strong>'+esc(t.brand)+'</strong><p>'+esc(t.copy)+'</p><small>Sample editorial content · No live news feed or real-time broadcast is connected.</small></div><div><b>Explore</b>'+data.pages.slice(1,9).map(p=>'<a href="#" data-nms-page="'+p.key+'">'+esc(p.title)+'</a>').join("")+'</div><div><b>About the publication</b><a href="#" data-nms-page="standards">Editorial standards</a><a href="#" data-nms-page="corrections">Corrections</a><a href="#" data-nms-page="privacy">Privacy</a><a href="#" data-nms-page="contact">Contact</a></div></footer><div class="nms-preview-note">DESIGN PREVIEW · Illustrative sample stories and imagery. No live reporting, subscriptions, tips or broadcasts are submitted.</div></div>';
$("wpTemplateName").textContent=t.name;$("wpTemplateTagline").textContent=t.short;$("wpTemplateAddress").textContent=location.origin+"/storefront.html?news-template="+t.key+"&page="+page;$("wpTemplateFeatureSummary").textContent="40 page types · 8 sample articles · 83 unique visual assets per template · responsive editorial layouts";$("wpTemplatePages").textContent="Explore 40 pages ↗";$("wpTemplatePagesBottom").textContent="Manage 40 pages ↗";$("wpTemplatePages").href="#nmsPageDirectory";$("wpTemplatePagesBottom").href="#nmsPageDirectory";$("wpTemplateUse").href="./website-builder.html?template="+encodeURIComponent(t.key);$("wpTemplateUseBottom").href=$("wpTemplateUse").href;
const url="./storefront.html?news-template="+encodeURIComponent(t.key)+"&page=home";["wpTemplateBrowserTop","wpTemplateBrowserBottom"].forEach(id=>{const a=$(id);a.href=url;a.dataset.previewReady="true";a.removeAttribute("aria-disabled");});
const status=$("wpTemplateConnection");status.textContent="NEWS & MEDIA · 4 DESIGNS";status.dataset.state="connected";status.title="Four local design systems and first-party image assets loaded.";
$("wpTemplateCategoryTitle").textContent="News & Media";$("wpTemplateIntro").textContent="Four independent publishing models: daily newspaper, business intelligence, culture magazine and broadcast network.";
document.querySelector(".hf-wpt-architecture p").textContent="Four distinct editorial businesses, 40 page types each, 8 illustrative launch stories and 83 unique visual assets per website. Sample content only; no live news feed or real subscriptions are connected.";
$("wpTemplateTabs").hidden=false;$("wpTemplateTabs").innerHTML=data.templates.map((x,i)=>'<button type="button" data-nms-template="'+i+'" class="'+(i===active?"is-active":"")+'" aria-pressed="'+(i===active)+'"><span class="hf-wpt-tab-number">0'+(i+1)+'</span><span><strong>'+esc(x.name)+'</strong><small>'+esc(x.short)+'</small></span></button>').join("");
const details=$("wpTemplateDetails");details.innerHTML='<article><small>BUSINESS MODEL</small><h3>'+esc(t.model)+'</h3><p>'+esc(t.audience)+'</p></article><article><small>VISUAL IDENTITY</small><h3>'+esc(t.layout)+'</h3><p>Palette '+esc(t.paper)+' / '+esc(t.accent)+' · '+esc(t.font)+' editorial typography.</p></article><article><small>CONVERSION & CONTENT</small><h3>'+esc(t.conversion)+'</h3><ul><li>40 meaningful page types</li><li>8 original illustrative editorial samples</li><li>83 unique page-assigned visual assets</li><li>Responsive navigation and local search preview</li><li>Publisher review required before launch</li></ul></article>';
const pageList='<section class="nms-page-directory" id="nmsPageDirectory"><div><small>COMPLETE SITE MAP</small><h2>Explore all 40 page types</h2></div><div>'+data.pages.map(p=>'<a href="#" data-nms-page="'+p.key+'"><span>'+String(data.pages.indexOf(p)+1).padStart(2,"0")+'</span>'+esc(p.title)+' ↗</a>').join("")+'</div></section>';
details.insertAdjacentHTML("afterend",pageList);
}
$("wpTemplateTabs").addEventListener("click",e=>{const b=e.target.closest("[data-nms-template]");if(!b)return;active=Number(b.dataset.nmsTemplate);page="home";query="";history.replaceState(null,"","?category=news-media&template="+(active+1));document.getElementById("nmsPageDirectory")?.remove();render();});
$("wpStorefront").addEventListener("click",e=>{const a=e.target.closest("[data-nms-page]");if(a){e.preventDefault();page=a.dataset.nmsPage;document.getElementById("nmsPageDirectory")?.remove();render();$("wpTemplateViewport").scrollIntoView({behavior:"smooth",block:"start"});return;}if(e.target.closest(".nms-menu"))$("wpStorefront").classList.toggle("nms-menu-open");});
$("wpStorefront").addEventListener("input",e=>{if(e.target.id==="nmsSearch"){query=e.target.value;const t=data.templates[active];const el=$("wpStorefront").querySelector(".nms-card-grid--page");if(el)el.innerHTML=data.templates[active].stories.filter(s=>!query||s.join(" ").toLowerCase().includes(query.toLowerCase())).map((s,i)=>card(t,s,i)).join("")||'<p class="nms-empty">No sample stories match that search.</p>'; }});
$("wpStorefront").addEventListener("submit",e=>{if(e.target.id!=="nmsNewsletter")return;e.preventDefault();const box=document.createElement("p");box.className="nms-form-note";box.textContent="Preview only — this email has not been stored or subscribed.";e.target.replaceWith(box);});
document.querySelectorAll("[data-preview-device]").forEach(b=>b.addEventListener("click",()=>{const mobile=b.dataset.previewDevice==="mobile";$("wpTemplateViewport").classList.toggle("is-mobile",mobile);$("wpTemplateViewport").classList.toggle("is-desktop",!mobile);document.querySelectorAll("[data-preview-device]").forEach(x=>{const on=x===b;x.classList.toggle("is-active",on);x.setAttribute("aria-pressed",String(on));});}));
fetch("/assets/news-media/templates.json").then(r=>{if(!r.ok)throw new Error("News & Media design data unavailable");return r.json();}).then(v=>{data=v;render();}).catch(err=>{console.error(err);$("wpTemplateConnection").textContent="NEWS & MEDIA ASSETS UNAVAILABLE";$("wpStorefront").hidden=false;$("wpStorefront").innerHTML='<p class="nms-empty">The News & Media design data could not be loaded. Refresh the page after deployment.</p>';});
})();

