-footer strong{font:900 24px Georgia,serif}.nms-footer p{max-width:400px;font-size:12px;line-height:1.6;opacity:.75}.nms-footer small{font-size:9px;opacity:.6}.nms-footer>div:not(:first-child){display:grid;align-content:start;gap:9px;font-size:11px}.nms-footer>div>b{margin-bottom:5px;color:var(--nms-accent)}.nms-preview-note{text-align:center;padding:10px;background:#e5e2da;color:#57534e;font:800 8px Arial,sans-serif;letter-spacing:.12em}.nms-page-directory{padding:26px 0}.nms-page-directory>div:first-child{padding:0 5%}.nms-page-directory small{font:800 9px Arial,sans-serif;letter-spacing:.16em;color:var(--nms-accent)}.nms-page-directory h2{font:700 24px Georgia,serif}.nms-page-directory>div:last-child{display:grid;grid-template-columns:repeat(4,1fr);gap:1px;background:#bbb}.nms-page-directory a{background:var(--nms-surface);padding:10px;font:700 10px Arial,sans-serif}.nms-page-directory a span{color:var(--nms-accent);margin-right:8px}.nms-empty,.nms-form-note{padding:30px;text-align:center;font:13px Arial,sans-serif}.nms-form-note{color:var(--nms-accent);font-weight:800}
