/* Standalone News & Media showcase runtime. Loaded before the shared commerce runtime. */
(function(){
"use strict";
const params=new URLSearchParams(location.search),key=params.get("news-template");
const root=document.getElementById("storefrontRoot");
const esc=v=>String(v??"").replace(/[&<>"']/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[c]));
const $=s=>root.querySelector(s);
let data,template,page=params.get("page")||"home",query="",menu=false;
const image=(path,alt,cls)=>path.includes("#")?'<svg class="'+(cls||"nms-image")+'" role="img" aria-label="'+esc(alt)+'"><use href="/'+esc(path)+'"></use></svg>':'<img class="'+(cls||"nms-image")+'" src="/'+esc(path)+'" alt="'+esc(alt)+'" loading="lazy">';
const url=k=>"?news-template="+encodeURIComponent(template.key)+"&page="+encodeURIComponent(k);
const label=k=>data.pages.find(p=>p.key===k)?.title||"Latest Stories";
function card(story,path,i){return '<article class="nms-story-card">'+image(path,story[0])+'<div class="nms-story-copy"><small>'+esc(story[1])+' · '+String(i+1).padStart(2,"0")+'</small><h3>'+esc(story[0])+'</h3><p>'+esc(story[2])+'</p><a href="'+url("article")+'" data-news-page="article">Read story ↗</a></div></article>';}
function home(){const p=template.pageImages.home;return '<section class="nms-hero"><div class="nms-hero-image">'+image(p[0],template.imageAlts[0],"nms-hero-photo")+'<span class="nms-hero-caption">ILLUSTRATIVE EDITORIAL PREVIEW</span></div><div class="nms-hero-copy"><small>'+esc(template.tag)+'</small><h1>'+esc(template.hero)+'</h1><p>'+esc(template.copy)+'</p><a class="nms-primary" href="'+url("latest")+'" data-news-page="latest">'+esc(template.cta)+' ↗</a><div class="nms-hero-meta"><span>Context before noise</span><span>Independent perspective</span></div></div></section><section class="nms-lead-grid"><article class="nms-lead-story"><div class="nms-lead-art">'+image(p[1],template.imageAlts[1])+'</div><div><small>EDITOR’S PICK · '+esc(template.stories[0][1])+'</small><h2>'+esc(template.stories[0][0])+'</h2><p>'+esc(template.stories[0][2])+'</p><a href="'+url("article")+'" data-news-page="article">Read the feature ↗</a></div></article><aside class="nms-side-stories"><small>MORE TO EXPLORE</small>'+template.stories.slice(1,4).map((s,i)=>'<a href="'+url("article")+'" data-news-page="article"><span>0'+(i+1)+'</span><div><small>'+esc(s[1])+'</small><strong>'+esc(s[0])+'</strong></div>↗</a>').join("")+'</aside></section><section class="nms-section"><div class="nms-section-head"><div><small>THE LATEST</small><h2>Stories worth your attention.</h2></div><a href="'+url("latest")+'" data-news-page="latest">All stories ↗</a></div><div class="nms-card-grid nms-card-grid--home">'+card(template.stories[4],p[2],0)+'<article class="nms-text-story"><small>EDITORIAL NOTE</small><h3>'+esc(template.stories[5][0])+'</h3><p>'+esc(template.stories[5][2])+'</p><a href="'+url("article")+'" data-news-page="article">Explore the story ↗</a></article><article class="nms-text-story"><small>IN FOCUS</small><h3>'+esc(template.stories[6][0])+'</h3><p>'+esc(template.stories[6][2])+'</p><a href="'+url("article")+'" data-news-page="article">Explore the story ↗</a></article></div></section><section class="nms-briefing"><div><small>THE DAILY BRIEFING</small><h2>Make space for informed reading.</h2><p>Get a considered selection of stories and explainers. This is a design preview, not an active subscription.</p></div><form id="nmsNewsletter"><input type="email" name="email" placeholder="Your email address" required aria-label="Email address"><button type="submit">Preview signup ↗</button></form></section>';}
function article(){const s=template.stories[0],p=template.pageImages.article;return '<section class="nms-page-hero"><div><small>'+esc(template.eyebrow)+' / FEATURE</small><h1>'+esc(s[0])+'</h1><p>'+esc(s[2])+'</p></div>'+image(p[0],s[0],"nms-page-hero-art")+'</section><article class="nms-article"><div class="nms-article-meta"><span>ILLUSTRATIVE EDITORIAL SAMPLE</span><span>6 MIN READ</span><span>EDITORIAL DESK</span></div><p class="nms-article-intro">'+esc(s[2])+'</p><h2>Start with the context</h2><p>This sample article demonstrates the long-form editorial layout. A real publisher can replace this copy with verified reporting, named authors, publication dates, source notes and relevant links before launch.</p>'+image(p[1],"Supporting editorial visual")+'<h2>What readers should take away</h2><p>Good journalism separates what is known, what remains uncertain and what deserves further investigation. Published stories should link to primary sources where possible and clearly label analysis, opinion and sponsored material.</p><blockquote>Clear context helps readers make sense of complex stories.</blockquote><p>Editorial content, quotes, dates and claims must be reviewed by the publisher before publication.</p><a class="nms-primary" href="'+url("latest")+'" data-news-page="latest">Back to latest stories ↗</a></article>';}
function content(){if(page==="home")return home();if(page==="article")return article();const p=template.pageImages[page]||template.pageImages.latest,stories=template.stories.filter(s=>!query||s.join(" ").toLowerCase().includes(query.toLowerCase())).slice(0,2);return '<section class="nms-page-hero"><div><small>'+esc(template.eyebrow)+' / '+esc(label(page).toUpperCase())+'</small><h1>'+esc(label(page))+'</h1><p>A carefully edited collection of reporting, useful context and perspectives from the '+esc(template.name)+' editorial team. All stories and examples are illustrative sample content.</p></div>'+image(p[0],label(page),"nms-page-hero-art")+'</section><section class="nms-topic-tools"><label>Search this section <input id="nmsSearch" value="'+esc(query)+'" placeholder="Search headlines, topics and ideas"></label><span>'+stories.length+' illustrative stories</span></section><section class="nms-card-grid nms-card-grid--page">'+stories.map((s,i)=>card(s,p[i+1],i)).join("")+'</section><section class="nms-more-links"><a href="'+url("newsletters")+'" data-news-page="newsletters">Get the briefing ↗</a><a href="'+url("standards")+'" data-news-page="standards">Editorial standards ↗</a><a href="'+url("contact")+'" data-news-page="contact">Contact the newsroom ↗</a></section>';}
function render(){const nav=data.pages.slice(1,8);document.title=template.name+" · News & Media Preview";document.body.dataset.template=template.key;let robots=document.querySelector('meta[name="robots"]');if(!robots){robots=document.createElement("meta");robots.name="robots";document.head.appendChild(robots);}robots.content="noindex,nofollow";root.innerHTML='<div class="nms-site" style="--nms-accent:'+template.accent+';--nms-ink:'+template.ink+';--nms-paper:'+template.paper+';--nms-surface:'+template.surface+';--nms-font:'+JSON.stringify(template.font)+'"><div class="nms-topline">'+esc(template.eyebrow)+' <span>ILLUSTRATIVE TEMPLATE PREVIEW · NOT LIVE NEWS</span></div><header class="nms-header"><a class="nms-brand" href="'+url("home")+'" data-news-page="home">'+esc(template.brand)+'<small>'+esc(template.short)+'</small></a><nav class="'+(menu?"is-open":"")+'">'+nav.map(p=>'<a href="'+url(p.key)+'" data-news-page="'+p.key+'">'+esc(p.title)+'</a>').join("")+'</nav><button type="button" class="nms-menu" aria-label="Toggle navigation" aria-expanded="'+menu+'">☰</button><a class="nms-header-cta" href="'+url("newsletters")+'" data-news-page="newsletters">Get the briefing ↗</a></header><main>'+content()+'</main><footer class="nms-footer"><div><strong>'+esc(template.brand)+'</strong><p>'+esc(template.copy)+'</p><small>No live news feed or real-time broadcast is connected.</small></div><div><b>Explore</b>'+data.pages.slice(1,9).map(p=>'<a href="'+url(p.key)+'" data-news-page="'+p.key+'">'+esc(p.title)+'</a>').join("")+'</div><div><b>Publication information</b><a href="'+url("standards")+'" data-news-page="standards">Editorial standards</a><a href="'+url("corrections")+'" data-news-page="corrections">Corrections</a><a href="'+url("privacy")+'" data-news-page="privacy">Privacy</a><a href="'+url("contact")+'" data-news-page="contact">Contact</a></div></footer><div class="nms-preview-note">DESIGN PREVIEW · Sample editorial content and imagery only. No live reporting, subscriptions, tips or broadcasts are submitted.</div></div>';bind();}
function bind(){root.querySelectorAll("[data-news-page]").forEach(a=>a.addEventListener("click",e=>{e.preventDefault();page=a.dataset.newsPage;query="";menu=false;history.pushState({page},"",url(page));render();window.scrollTo({top:0,behavior:"smooth"});}));root.querySelector(".nms-menu")?.addEventListener("click",()=>{menu=!menu;root.querySelector(".nms-header nav")?.classList.toggle("is-open",menu);root.querySelector(".nms-menu")?.setAttribute("aria-expanded",String(menu));});root.querySelector("#nmsSearch")?.addEventListener("input",e=>{query=e.target.value;const p=template.pageImages[page]||template.pageImages.latest,stories=template.stories.filter(s=>!query||s.join(" ").toLowerCase().includes(query.toLowerCase())).slice(0,2);const el=root.querySelector(".nms-card-grid--page");if(el)el.innerHTML=stories.map((s,i)=>card(s,p[i+1],i)).join("")||'<p class="nms-empty">No sample stories match that search.</p>';});root.querySelector("#nmsNewsletter")?.addEventListener("submit",e=>{e.preventDefault();const p=document.createElement("p");p.className="nms-form-note";p.textContent="Preview only — no email was stored or subscribed.";e.target.replaceWith(p);});}
window.addEventListener("popstate",()=>{const p=new URLSearchParams(location.search);page=p.get("page")||"home";render();});
function start(){if(!key)return;fetch("/assets/news-media/templates.json").then(r=>{if(!r.ok)throw new Error("Design data unavailable");return r.json();}).then(v=>{data=v;template=data.templates.find(t=>t.key===key);if(!template)throw new Error("Unknown News & Media template");render();}).catch(err=>{console.error(err);root.innerHTML='<main class="nms-site"><p class="nms-empty">News & Media preview could not be loaded. Please return to the template studio.</p></main>';});}
window.NewsMediaStandalone={start};
})();

