:16px/1.8 Arial,sans-serif;max-width:560px;opacity:.75}.nms-hero-meta{display:flex;gap:22px;margin-top:30px;padding-top:16px;border-top:1px solid #8884;font:700 10px Arial,sans-serif;opacity:.65}.nms-lead-grid{display:grid;grid-template-columns:1.4fr .8fr;gap:40px;padding:55px 6%;border-bottom:1px solid #8884}.nms-lead-story{display:grid;grid-template-columns:1fr 1fr;gap:28px;align-items:center}.nms-lead-art{height:280px;overflow:hidden}.nms-lead-story h2{font-size:clamp(25px,3vw,38px);line-height:1.05;margin:14px 0}.nms-lead-story p,.nms-story-copy p{font:13px/1.75 Arial,sans-serif;opacity:.72}.nms-lead-story a,.nms-story-copy a{font:800 11px Arial,sans-serif;color:var(--nms-accent)}.nms-side-stories{border-left:1px solid #8884;padding-left:28px}.nms-side-stories>small{font:800 10px Arial,sans-serif;letter-spacing:.16em;color:var(--nms-accent)}.nms-side-stories>a{display:grid;grid-template-columns:30px 1fr 14px;gap:12px;padding:17px 0;border-bottom:1px solid #8884;align-items:start}.nms-side-stories>a>span{font:800 11px Arial,sans-serif;color:var(--nms-accent)}.nms-side-stories a small,.nms-side-stories a strong{display:block}.nms-side-stories a small{font:800 9px Arial,sans-serif;opacity:.55}.nms-side-stories a strong{font-size:16px;line-height:1.25;margin-top:6px}.nms-section{padding:55px 6%}.nms-section-head{display:flex;align-items:end;justify-content:space-between;margin-bottom:24px}.nms-section-head h2{font-size:clamp(28px,3vw,42px);margin:9px 0 0}.nms-section-head>a{font:800 11px Arial,sans-serif;color:var(--nms-accent)}.nms-card-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:20px}.nms-story-card{background:var(--nms-surface);min-width:0}.nms-story-card>.nms-image{height:190px}.nms-story-copy{padding:19px}.nms-story-copy small{font:800 9px Arial,sans-serif;letter-spacing:.12em;color:var(--nms-accent)}.nms-story-copy h3{font-size:21px;line-height:1.1;margin:11px 0}.nms-text-story{padding:22px;border:1px solid #8885;background:transparent}.nms-text-story small{font:800 9px Arial,sans-serif;color:var(--nms-accent);letter-spacing:.12em}.nms-text-story h3{font-size:22px;line-height:1.1}.nms-text-story p{font:13px/1.7 Arial,sans-serif;opacity:.72}.nms-text-story a{font:800 10px Arial,sans-serif;color:var(--nms-accent)}.nms-briefing{padding:42px 6%;background:var(--nms-ink);color:white;display:flex;align-items:center;justify-content:space-between;gap:30px}.nms-briefing h2{font-size:30px;margin:9px 0}.nms-briefing p{font:12px/1.7 Arial,sans-serif;opacity:.7;max-width:550px}.nms-briefing form{display:flex;gap:8px;min-width:320px}.nms-briefing input,.nms-topic-tools input{min-width:0;width:100%;padding:13px;border:1px solid #8888;background:var(--nms-surface);color:var(--nms-ink)}.nms-briefing button{border:0;padding:0 16px;background:var(--nms-accent);color:white;font:800 10px Arial,sans-serif;white-space:nowrap}.nms-page-hero{padding:55px 6%;display:grid;grid-template-columns:1fr minmax(260px,34%);gap:35px;align-items:center;background:var(--nms-surface);border-bottom:1px solid #8884}.nms-page-hero h1{font-size:clamp(42px,5vw,68px);line-height:1;margin:16px 0}.nms-page-hero-art{height:270px}.nms-topic-tools{display:flex;align-items:end;justify-content:space-between;gap:20px;padding:30px 6% 12px;font:11px Arial,sans-serif}.nms-topic-tools label{display:grid;gap:8px;font-weight:700}.nms-topic-tools input{width:min(380px,65vw);border-color:#8885}.nms-card-grid--page{padding:15px 6% 55px;grid-template-columns:repeat(2,minmax(0,1fr))}.nms-article{max-width:800px;margin:50px auto;padding:0 25px;font:17px/1.9 Georgia,serif}.nms-article-meta{display:flex;gap:20px;flex-wrap:wrap;font:800 9px Arial,sans-serif;color:var(--nms-accent);letter-spacing:.12em}.nms-article-intro{font-size:24px;line-height:1.45}.nms-article h2{font-size:30px;line-height:1.15;margin:35px 0 12px}.nms-article>svg,.nms-article>img{width:100%;height:auto;max-height:420px;margin:28px 0}.nms-article blockquote{border-left:4px solid var(--nms-accent);margin:30px 0;padding:8px 22px;font-size:27px;line-height:1.35}.nms-more-links{display:flex;flex-wrap:wrap;gap:22px;padding:25px 6%;border-top:1px solid #8884;font:800 11px Arial,sans-serif;color:var(--nms-accent)}.nms-footer{display:grid;grid-template-columns:2fr 1fr 1fr;gap:35px;padding:45px 6%;background:var(--nms-ink);color:#fff;font-family:Arial,sans-serif}.nms-footer strong{font:900 27px Georgia,serif}.nms-footer p{max-width:440px;font-size:13px;line-height:1.7;opacity:.75}.nms-footer small{font-size:10px;opacity:.6}.nms-footer>div:not(:first-child){display:grid;align-content:start;gap:10px;font-size:12px}.nms-footer>div>b{margin-bottom:6px;color:var(--nms-accent)}.nms-preview-note{text-align:center;padding:12px;background:#e5e2da;color:#57534e;font:800 9px Arial,sans-serif;letter-spacing:.12em}.nms-empty,.nms-form-note{padding:35px;text-align:center;font:14px Arial,sans-serif}.nms-form-note{color:var(--nms-accent);font-weight:800}
@media(max-width:900px){.nms-header nav{display:none}.nms-menu{display:block}.nms-header nav.is-open{display:flex;position:absolute;z-index:10;top:90px;left:0;right:0;padding:18px 5%;background:var(--nms-surface);flex-wrap:wrap;box-shadow:0 12px 24px #0002}.nms-hero,.nms-lead-grid,.nms-lead-story,.nms-page-hero{grid-template-columns:1fr}.nms-hero-image{min-height:280px}.nms-hero-copy{padding:36px 6%}.nms-lead-grid{gap:25px}.nms-side-stories{border-left:0;padding-left:0}.nms-card-grid{grid-template-columns:repeat(2,minmax(0,1fr))}.nms-briefing{display:grid}.nms-briefing form{min-width:0}.nms-footer{grid-template-columns:1fr 1fr}.nms-footer>div:first-child{grid-column:1/-1}}
@media(max-width:560px){.nms-topline span{display:none}.nms-header{padding:16px 5%}.nms-brand{font-size:22px}.nms-header-cta{display:none}.nms-hero-image{min-height:220px}.nms-hero h1{font-size:43px}.nms-hero-meta{gap:12px;font-size:9px}.nms-lead-grid{padding:32px 5%}.nms-section{padding:34px 5%}.nms-card-grid,.nms-card-grid--page{grid-template-columns:1fr}.nms-briefing{padding:32px 5%}.nms-briefing form{display:grid}.nms-briefing button{min-height:42px}.nms-page-hero{padding:34px 5%}.nms-page-hero-art{height:200px}.nms-topic-tools{padding:24px 5%}.nms-footer{grid-template-columns:1fr;padding:34px 5%}.nms-footer>div:first-child{grid-column:auto}.nms-more-links{padding:22px 5%}}

